@font-face {
  font-family: boxicons;
  font-style: normal;
  font-weight: 400;
  src: url("https://www.raysteedsinfotech.com/fonts/boxicons.woff2") format("woff2");
}

.bx {
  display: inline-block;
  font-style: normal;
  font-variant: normal;
  font-weight: 400;
  line-height: 1;
  text-rendering: auto;
  text-transform: none;
  speak: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-family: boxicons !important;
}

.bx-ul {
  list-style: none;
  margin-left: 2em;
  padding-left: 0;
}

.bx-ul > li {
  position: relative;
}

.bx-ul .bx {
  font-size: inherit;
  left: -2em;
  line-height: inherit;
  position: absolute;
  text-align: center;
  width: 2em;
}

@keyframes spin {
  0% {
    transform: rotate(0);
  }

  to {
    transform: rotate(359deg);
  }
}

@keyframes burst {
  0% {
    opacity: 1;
    transform: scale(1);
  }

  90% {
    opacity: 0;
    transform: scale(1.5);
  }
}

@keyframes flashing {
  0% {
    opacity: 1;
  }

  45% {
    opacity: 0;
  }

  90% {
    opacity: 1;
  }
}

@keyframes fade-left {
  0% {
    opacity: 1;
    transform: translateX(0);
  }

  75% {
    opacity: 0;
    transform: translateX(-20px);
  }
}

@keyframes fade-right {
  0% {
    opacity: 1;
    transform: translateX(0);
  }

  75% {
    opacity: 0;
    transform: translateX(20px);
  }
}

@keyframes fade-up {
  0% {
    opacity: 1;
    transform: translateY(0);
  }

  75% {
    opacity: 0;
    transform: translateY(-20px);
  }
}

@keyframes fade-down {
  0% {
    opacity: 1;
    transform: translateY(0);
  }

  75% {
    opacity: 0;
    transform: translateY(20px);
  }
}

@keyframes tada {
  0% {
    transform: scaleX(1);
  }

  10%, 20% {
    transform: scale3d(.95, .95, .95)rotate(-10deg);
  }

  30%, 50%, 70%, 90% {
    transform: scaleX(1)rotate(10deg);
  }

  40%, 60%, 80% {
    transform: rotate(-10deg);
  }

  to {
    transform: scaleX(1);
  }
}

.bx-spin, .bx-spin-hover:hover, .bx-spin-hover.\:hover {
  animation: 2s linear infinite spin;
}

.bx-tada, .bx-tada-hover:hover, .bx-tada-hover.\:hover {
  animation: 1.5s infinite tada;
}

.bx-flashing, .bx-flashing-hover:hover, .bx-flashing-hover.\:hover {
  animation: 1.5s linear infinite flashing;
}

.bx-burst, .bx-burst-hover:hover, .bx-burst-hover.\:hover {
  animation: 1.5s linear infinite burst;
}

.bx-fade-up, .bx-fade-up-hover:hover, .bx-fade-up-hover.\:hover {
  animation: 1.5s linear infinite fade-up;
}

.bx-fade-down, .bx-fade-down-hover:hover, .bx-fade-down-hover.\:hover {
  animation: 1.5s linear infinite fade-down;
}

.bx-fade-left, .bx-fade-left-hover:hover, .bx-fade-left-hover.\:hover {
  animation: 1.5s linear infinite fade-left;
}

.bx-fade-right, .bx-fade-right-hover:hover, .bx-fade-right-hover.\:hover {
