/* Filter Buttons */
       .gallery .filter-btn {
            border: 2px solid #0d233a;
            color: #0d233a;
            font-weight: 600;
            border-radius: 30px !important;
            padding: 8px 25px;
            margin: 5px;
            transition: 0.3s;
        }
        .gallery-box a{
          width:100%;
        }
        .gallery .filter-btn.active, .filter-btn:hover {
            background-color: #ff5e14;
            border-color: #ff5e14;
            color: white;
            border-radius: 30px !important;
        }

        /* Gallery Grid */
        .gallery-item {
            position: relative;
            overflow: hidden;
            border-radius: 12px;
            cursor: pointer;
            height: 250px;
        }
        .gallery-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }
        .gallery-item:hover img {
            transform: scale(1.1);
        }
        .overlay {
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(13, 35, 58, 0.7);
            display: flex; align-items: center; justify-content: center;
            opacity: 0; transition: 0.4s;
        }
        .gallery-item:hover .overlay { opacity: 1; }
        .overlay i { color: white; font-size: 2rem; }

        /* Animation for Filtering */
        .fade-in { animation: fadeIn 0.5s ease-in; }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .fancybox__container {
    z-index: 9999 !important;
}


